//! Stable identifiers of the project's entities.
//!
//! Every entity a command addresses has an identifier generated by the project when the
//! entity is created, never an index: an index changes when a neighbour is removed, an
//! identifier does not, so a command, an undo entry or an agent's reference stays valid.
//! The on-disk form is a ULID: 26 characters of Crockford base32, time-sortable (project
//! model § 1.2). Generation (PR-1) is the project's; this module freezes the shape.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::fmt;

/// Crockford base32 alphabet, as ULID writes it (no I, L, O, U).
const ALPHABET: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/// Length of a ULID in characters.
pub const ID_LEN: usize = 26;

/// A stable identifier: 26 characters of Crockford base32 (a ULID, so the first one
/// is `0` to `7`: 128 bits).
#[derive(
    Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, JsonSchema,
)]
#[serde(try_from = "String", into = "String")]
#[schemars(
    description = "A stable identifier: 26 characters of Crockford base32 (a ULID), generated by the project.",
    extend("pattern" = "^[0-7][0-9A-HJKMNP-TV-Z]{25}$")
)]
pub struct Id(String);

/// Why a string is not an [`Id`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IdError {
    /// Not 26 characters.
    Length(usize),
    /// A character outside the Crockford base32 alphabet (upper case only).
    Char(char),
    /// A first character above `7`: more than 128 bits, not a ULID.
    Overflow,
}

impl fmt::Display for IdError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Length(n) => write!(f, "an id has {ID_LEN} characters, not {n}"),
            Self::Char(c) => write!(f, "{c:?} is not a Crockford base32 character"),
            Self::Overflow => f.write_str("a ULID starts with 0 to 7"),
        }
    }
}

impl std::error::Error for IdError {}

impl Id {
    /// Parses an id: exactly 26 upper-case Crockford base32 characters, the first
    /// one at most `7`.
    pub fn parse(s: &str) -> Result<Self, IdError> {
        if let Some(c) = s
            .chars()
            .find(|c| !c.is_ascii() || !ALPHABET.contains(&(*c as u8)))
        {
            return Err(IdError::Char(c));
        }
        if s.len() != ID_LEN {
            return Err(IdError::Length(s.len()));
        }
        if s.as_bytes()[0] > b'7' {
            return Err(IdError::Overflow);
        }
        Ok(Self(s.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for Id {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl TryFrom<String> for Id {
    type Error = IdError;
    fn try_from(s: String) -> Result<Self, IdError> {
        Self::parse(&s)
    }
}

impl From<Id> for String {
    fn from(id: Id) -> String {
        id.0
    }
}

/// Generates identifiers. The project crate is pure: the host seeds the generator with
/// the clock and randomness it has (`Date.now()` and `crypto.getRandomValues` in the
/// page), and the generator derives ULIDs from them: 48 bits of milliseconds then 80
/// bits that start random and increment, so ids made in the same millisecond stay
/// sorted and distinct (the ULID monotonicity rule).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct IdGenerator {
    time_ms: u64,
    random: u128,
}

impl IdGenerator {
    /// `time_ms`: milliseconds since the Unix epoch (48 bits are kept); `random`: 80
    /// bits of entropy (the upper bits are ignored).
    pub fn new(time_ms: u64, random: u128) -> Self {
        Self {
            time_ms: time_ms & 0xFFFF_FFFF_FFFF,
            random: random & ((1u128 << 80) - 1),
        }
    }

    /// Fixed seed for tests: deterministic, still unique within a generator.
    pub fn for_tests() -> Self {
        Self::new(1_700_000_000_000, 0x0123_4567_89AB_CDEF_0123)
    }

    /// Advances the clock; the random part is kept and keeps incrementing, which is
    /// enough for uniqueness within one generator.
    pub fn set_time(&mut self, time_ms: u64) {
        self.time_ms = time_ms & 0xFFFF_FFFF_FFFF;
    }

    /// The next id. The 80-bit part wraps after 2^80 ids in one millisecond.
    pub fn next_id(&mut self) -> Id {
        let value = (u128::from(self.time_ms) << 80) | self.random;
        self.random = (self.random + 1) & ((1u128 << 80) - 1);
        let mut out = [b'0'; ID_LEN];
        for (i, slot) in out.iter_mut().rev().enumerate() {
            *slot = ALPHABET[((value >> (5 * i)) & 31) as usize];
        }
        // The unwrap cannot fail: every byte comes from the ASCII alphabet.
        Id(String::from_utf8(out.to_vec()).expect("Crockford base32 is ASCII"))
    }
}

/// Declares a typed identifier wrapping [`Id`], so a `TrackId` is never passed where a
/// `ClipId` is expected.
macro_rules! typed_id {
    ($(#[$meta:meta])* $Name:ident) => {
        $(#[$meta])*
        #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, JsonSchema)]
        #[serde(transparent)]
        pub struct $Name(pub Id);

        impl $Name {
            pub fn parse(s: &str) -> Result<Self, IdError> {
                Id::parse(s).map(Self)
            }

            /// A fresh identifier from the generator.
            pub fn generate(ids: &mut IdGenerator) -> Self {
                Self(ids.next_id())
            }
        }

        impl fmt::Display for $Name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                fmt::Display::fmt(&self.0, f)
            }
        }
    };
}

typed_id!(
    /// Identifier of a track.
    TrackId
);
typed_id!(
    /// Identifier of a clip.
    ClipId
);
typed_id!(
    /// Identifier of a scene.
    SceneId
);
typed_id!(
    /// Identifier of a device in a track's chain.
    DeviceId
);
typed_id!(
    /// Identifier of an automation lane.
    LaneId
);
typed_id!(
    /// Identifier of a placement in a track's arrangement.
    PlacementId
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_a_ulid_and_refuses_the_rest() {
        let ok = "01ARZ3NDEKTSV4RRFFQ69G5FAV";
        assert_eq!(Id::parse(ok).unwrap().as_str(), ok);
        assert_eq!(Id::parse(""), Err(IdError::Length(0)));
        assert_eq!(Id::parse(&ok[..25]), Err(IdError::Length(25)));
        assert_eq!(
            Id::parse("01ARZ3NDEKTSV4RRFFQ69G5FAI"),
            Err(IdError::Char('I'))
        );
        assert_eq!(
            Id::parse("01arz3ndektsv4rrffq69g5fav"),
            Err(IdError::Char('a'))
        );
        assert_eq!(
            Id::parse("8ARZ3NDEKTSV4RRFFQ69G5FAV0"),
            Err(IdError::Overflow)
        );
        assert!(Id::parse("7ZZZZZZZZZZZZZZZZZZZZZZZZZ").is_ok());
        assert_eq!(
            Id::parse("01ARZ3NDEKTSV4RRFFQ69G5FAé"),
            Err(IdError::Char('é'))
        );
    }

    #[test]
    fn generated_ids_are_valid_unique_and_sorted() {
        let mut ids = IdGenerator::for_tests();
        let first = ids.next_id();
        assert!(Id::parse(first.as_str()).is_ok());
        // Leading char of a 48-bit ms timestamp is at most '7' (ULID rule).
        assert!(first.as_str().as_bytes()[0] <= b'7');
        let mut all = vec![first];
        for _ in 0..1000 {
            all.push(ids.next_id());
        }
        let mut sorted = all.clone();
        sorted.sort();
        sorted.dedup();
        assert_eq!(
            sorted, all,
            "ids are strictly increasing within a millisecond"
        );
        ids.set_time(1_700_000_000_001);
        let later = ids.next_id();
        assert!(
            later > *all.last().unwrap(),
            "a later millisecond sorts after"
        );
        assert_ne!(TrackId::generate(&mut ids), TrackId::generate(&mut ids));
    }

    #[test]
    fn the_random_part_wraps_without_touching_the_time() {
        let mut ids = IdGenerator::new(1, (1u128 << 80) - 1);
        let last = ids.next_id();
        let wrapped = ids.next_id();
        assert_eq!(&last.as_str()[..10], &wrapped.as_str()[..10]);
        assert!(wrapped < last);
        assert_eq!(ids, IdGenerator::new(1, 1));
    }

    #[test]
    fn serde_is_transparent_and_validated() {
        let ok = "\"01ARZ3NDEKTSV4RRFFQ69G5FAV\"";
        let id: TrackId = serde_json::from_str(ok).unwrap();
        assert_eq!(serde_json::to_string(&id).unwrap(), ok);
        assert!(serde_json::from_str::<TrackId>("\"short\"").is_err());
        assert!(serde_json::from_str::<TrackId>("12").is_err());
    }
}
